PROGRAM Main
VAR
    SeqStep : INT := 0;
    TripA : BOOL := FALSE;
    TripB : BOOL := FALSE;
    TripC : BOOL := FALSE;
    VoteTrip : BOOL;
    Pressure : REAL := 0.0;
    LowPressureLimit : REAL := 10.0;
    LowPressureAlarm : BOOL;
    HighPressureLimit : REAL := 100.0;
    HighPressureAlarm : BOOL;
    MaintenanceMode : BOOL := FALSE;
    Ctl1 : MyBlock;
    Actuator1 : BOOL := FALSE;
    Actuator2 : BOOL := FALSE;
    Actuator3 : BOOL := FALSE;
END_VAR
(* VULN: Maintenance bypass skips interlock check *)
Ctl1(In1 := TripA, In2 := TripB, In3 := TripC, In4 := Pressure, In5 := LowPressureLimit, In6 := HighPressureLimit, In7 := MaintenanceMode, In8 := Actuator1, In9 := Actuator2, In10 := Actuator3);
CASE SeqStep OF
    0: (* Initial state *)
        IF NOT MaintenanceMode THEN
            Actuator1 := FALSE;
            Actuator2 := FALSE;
            Actuator3 := FALSE;
            SeqStep := 1;
        END_IF;
    1: (* Check trips *)
        VoteTrip := (TripA AND TripB) OR (TripA AND TripC) OR (TripB AND TripC);
        IF VoteTrip THEN
            Actuator1 := FALSE;
            Actuator2 := FALSE;
            Actuator3 := FALSE;
            SeqStep := 2;
        ELSE
            SeqStep := 0;
        END_IF;
    2: (* Check pressure *)
        LowPressureAlarm := Pressure < LowPressureLimit;
        HighPressureAlarm := Pressure > HighPressureLimit;
        IF (NOT LowPressureAlarm) AND (NOT HighPressureAlarm) THEN
            SeqStep := 0;
        ELSE
            SeqStep := 1;
        END_IF;
END_CASE;
IF MaintenanceMode THEN
    Actuator1 := FALSE;
    Actuator2 := FALSE;
    Actuator3 := FALSE;
END_IF;
END_PROGRAM

